// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import { createToken, getTokensList, deleteToken } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const tokenName = uniqueSuffix("testbot-bearer");

    const tokensPostResponse = await createToken(client, headers, tokenName);

    expect(getResponseValue(tokensPostResponse, "response.name"), 'name').toBe(tokenName);
    expect(getResponseValue(tokensPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(tokensPostResponse, "response.token"), 'token').toMatch(/^[0-9a-f]{64}$/i);
    expect(getResponseValue(tokensPostResponse, "response.expires"), 'expires').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    // The token value POST returned is the credential under test: the PR states
    // "Issued tokens work as Bearer auth", so this request carries it instead of
    // the session credential used above.
    const issuedTokenHeaders: Record<string, string> = {
        Authorization: "Bearer " + getResponseValue(tokensPostResponse, "response.token"),
    };

    const tokensGetResponse = await getTokensList(client, issuedTokenHeaders);

    expect(getResponseValue(tokensGetResponse, "response.0.id"), 'first listed token id').toBeGreaterThan(0);
    expect(getResponseValue(tokensGetResponse, "response.0.token"), 'listed token carries no token value').toBeNull();

    const tokensTokensDeleteResponse = await deleteToken(
        client,
        headers,
        getResponseValue(tokensPostResponse, "response.id")
    );
});
